def _items(state: Mapping[str, Any], key: str) -> list[dict[str, Any]]:
    rows = state.get(key)
    return [dict(row) for row in rows if isinstance(row, Mapping)] if isinstance(rows, list) else []


def _number(value: Any) -> float:
    try:
        return float(value)
    except (TypeError, ValueError):
        return float("nan")


def _subset(row: Mapping[str, Any], expected: Mapping[str, Any]) -> bool:
    return all((_number(row.get(k)) == v if isinstance(v, float) else row.get(k) == v) for k, v in expected.items())


def _summary(row: Mapping[str, Any]) -> dict[str, Any]:
    keys = {"seq", "type", "alertId", "cardId", "accountId", "status", "settingId", "threshold", "enabled", "email", "sms", "push", "delivery", "month", "filename", "recipientId", "recipientName", "bank", "mask", "transferId", "paymentId", "billerId", "fromAccountId", "amount", "scheduledDate", "memo"}
    return {key: row.get(key) for key in keys if key in row}


